def cache_key(tenant, task_digest, policy_version, deployment_revision):
    import hashlib
    import json

    values = [tenant, task_digest, policy_version, deployment_revision]
    if any(not isinstance(value, str) or not value.strip() for value in values):
        raise ValueError("All cache key fields must be nonblank strings")

    try:
        canonical = json.dumps(values, ensure_ascii=False, separators=(",", ":"))
        return hashlib.sha256(canonical.encode("utf-8")).hexdigest()
    except UnicodeEncodeError as exc:
        raise ValueError("Cache key fields must be valid UTF-8 strings") from exc
